CREATE TABLE users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('student','parent','teacher','admin','superadmin','invigilator','examiner')),approval TEXT NOT NULL DEFAULT 'pending' CHECK(approval IN ('pending','approved','rejected')),verified INTEGER NOT NULL DEFAULT 0,created TEXT NOT NULL);
CREATE TABLE verification_tokens(digest TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires REAL NOT NULL);
CREATE TABLE students(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,user_id TEXT UNIQUE REFERENCES users(id),family_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,dob TEXT,photo_id TEXT,created TEXT NOT NULL);
CREATE TABLE parent_students(parent_id TEXT REFERENCES users(id),student_id TEXT REFERENCES students(id),PRIMARY KEY(parent_id,student_id));
CREATE TABLE teachers(user_id TEXT PRIMARY KEY REFERENCES users(id));
CREATE TABLE subjects(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE subject_levels(id TEXT PRIMARY KEY,subject_id TEXT NOT NULL REFERENCES subjects(id),name TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(ordinal>0),fee INTEGER NOT NULL CHECK(fee>=0),UNIQUE(subject_id,ordinal));
CREATE TABLE teacher_subjects(teacher_id TEXT REFERENCES teachers(user_id),subject_id TEXT REFERENCES subjects(id),PRIMARY KEY(teacher_id,subject_id));
CREATE TABLE uploads(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),student_id TEXT REFERENCES students(id),kind TEXT NOT NULL CHECK(kind IN ('photo','signature')),path TEXT NOT NULL UNIQUE,mime TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE applications(id TEXT PRIMARY KEY,student_id TEXT NOT NULL REFERENCES students(id),year INTEGER NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'draft',draft TEXT NOT NULL DEFAULT '{}',candidate_name TEXT,dob TEXT,photo_id TEXT REFERENCES uploads(id),signature_id TEXT REFERENCES uploads(id),guardian TEXT NOT NULL DEFAULT '',submitted TEXT,UNIQUE(student_id,year));
CREATE TABLE application_subjects(id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES applications(id),subject_id TEXT NOT NULL REFERENCES subjects(id),level_id TEXT NOT NULL REFERENCES subject_levels(id),teacher_id TEXT NOT NULL REFERENCES teachers(user_id),index_number TEXT NOT NULL UNIQUE,fee INTEGER NOT NULL CHECK(fee>=0),status TEXT NOT NULL DEFAULT 'pending',reason TEXT,teacher_signature TEXT REFERENCES uploads(id),submitted TEXT NOT NULL,UNIQUE(application_id,subject_id,level_id));
CREATE TABLE payment_allocations(id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES applications(id),teacher_id TEXT NOT NULL REFERENCES teachers(user_id),amount INTEGER NOT NULL CHECK(amount>0),method TEXT NOT NULL CHECK(method IN ('card','etransfer','teacher')),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','failed','refunded')),reference TEXT,request_key TEXT NOT NULL UNIQUE,created TEXT NOT NULL);
CREATE TABLE refund_jobs(id TEXT PRIMARY KEY,subject_entry TEXT NOT NULL UNIQUE REFERENCES application_subjects(id),amount INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',reason TEXT NOT NULL);
CREATE TABLE notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),application_id TEXT REFERENCES applications(id),event TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_attempt REAL NOT NULL DEFAULT 0,last_error TEXT,attachment_entry TEXT,created TEXT NOT NULL);
CREATE TABLE exam_sessions(id TEXT PRIMARY KEY,name TEXT NOT NULL,venue TEXT NOT NULL,start TEXT NOT NULL,end TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0),buffer_minutes INTEGER NOT NULL DEFAULT 15 CHECK(buffer_minutes>=0),subject_id TEXT REFERENCES subjects(id));
CREATE TABLE session_staff(session_id TEXT REFERENCES exam_sessions(id),user_id TEXT REFERENCES users(id),PRIMARY KEY(session_id,user_id));
CREATE TABLE admissions(id TEXT PRIMARY KEY,entry_id TEXT NOT NULL UNIQUE REFERENCES application_subjects(id),session_id TEXT NOT NULL REFERENCES exam_sessions(id),code TEXT NOT NULL UNIQUE,used_at TEXT);
CREATE TABLE results(entry_id TEXT PRIMARY KEY REFERENCES application_subjects(id),marks REAL NOT NULL CHECK(marks>=0 AND marks<=100),grade TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN ('pass','fail')),status TEXT NOT NULL CHECK(status IN ('draft','submitted','published')),official_signature TEXT NOT NULL DEFAULT '',updated TEXT NOT NULL);
CREATE TABLE ceremony_blocks(id TEXT PRIMARY KEY,name TEXT NOT NULL,venue TEXT NOT NULL,start TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0));
CREATE TABLE ceremony_assignments(student_id TEXT REFERENCES students(id),year INTEGER NOT NULL,block_id TEXT NOT NULL REFERENCES ceremony_blocks(id),PRIMARY KEY(student_id,year));
CREATE TABLE audit_logs(id TEXT PRIMARY KEY,actor TEXT REFERENCES users(id),action TEXT NOT NULL,target TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT INTO settings VALUES('minimum_age','6');
CREATE INDEX teacher_queue ON application_subjects(teacher_id,status,submitted,id);
CREATE INDEX allocations_application ON payment_allocations(application_id,teacher_id,status);
CREATE INDEX notifications_due ON notifications(status,next_attempt);
CREATE INDEX students_family ON students(family_id);
